| -القدرة على توظيف تقنيات وإجراءات مهارة الربط بين الأفكار؛ | (3ن) |
| -سلامة اللغة واحترام علامات الترقيم. | (2ن) |$sujet$,
  $sujet${"parties": [{"titre": "المجال الأول: مكون النصوص", "points": 10, "questions": [{"type": "libre", "numero": "1", "points": 1, "enonce": "تأمل(ي) **عنوان النص وبدايته**، ثم أبرز(ي) **علاقتهما بموضوعه**", "correction": "يفترض أن يحدد المترشح علاقة المؤشرين بموضوع النص، وهي علاقة ترابط وتكامل / تفسير وتوضيح."}, {"type": "libre", "numero": "2", "points": 1, "enonce": "حدد(ي) **القضية الأساس** التي يطرحها النص", "correction": "القضية المحورية للنص مفادها: أبعاد الإنجاز التاريخي للمنتخب الوطني في كأس العالم وما حققه من مكاسب. (تقبل كل فكرة مناسبة تصب في موضوع النص) ."}, {"type": "libre", "numero": "3", "points": 1, "enonce": "اشرح(ي) قول الكاتب في **حدود أربعة أسطر**: **\"أضحى الفريق الوطني الحزب الأكثر تأثيرا في المُجتمع المغربيّ حاليا، وبمسافة شاسعة عن أي جماعة أخرى\"**", "correction": "تقبل كل فكرة يبين فيها المترشح فهمه السليم لقول الكاتب، مع سلامة اللغة والالتزام بعدد الأسطر."}, {"type": "libre", "numero": "4", "points": 1.5, "enonce": "يتجاذب النص حقلان دلاليان بارزان، **حددهما**، ثم مثل لكل واحد منهما **بأربعة ألفاظ أو عبارات**، مصنفا ذلك في جدول من خانتين", "correction": "تحديد الحقلين الدلالين البارزين في النص: حقل الرياضة / حقل السياسة . 0.5ن. التمثيل لكل واحد منهما بأربعة ألفاظ أو عبارات (تقبل كل الألفاظ أو العبارات، شريطة ورودها في النص، والتزام المترشح بالعدد المطلوب منه): حقل الرياضة 0.5ن: الفريق المغربي، كرة القدم، مونديال قطر، التشجيع، مواجهات حاسمة، المشجعون، انتصار، نجوم الفريق، مربع الكبار، تصنيف الفيفا...... / حقل السياسة 0.5ن: النخب، الواقع السياسي، المشهد السياسي، الحشد الجماهيري، الحزب، المجتمع المغربي، النشيد الوطني، الوطنية، النشيد الوطني، رموز البلد، الفخر الوطني......"}, {"type": "libre", "numero": "5", "points": 1.5, "enonce": "استخرج(ي) من **الفقرتين الأخيرتين** من النص، **ثلاثة مكاسب** سياسية حققها الفريق الوطني من إنجازه الكروي في المونديال", "correction": "جرد المترشح(ة) ثلاثة مكاسب سياسية حققها المنتخب الوطني، انطلاقا من الفقرتين الأخيرتين: -تفوق نجوم الفريق على سائر النخب –لعب الفريق دورا رمزيا في توحيد ما يفرقه الواقع السياسي –أضحى الحزب الأوسع تأثيرا في المجتمع –ساهم في تحريك المشاعر العاطفية الاجتماعية –إذكاء مشاعر القومية –تعزيز الوطنية –جعل المغاربة فخورين بوطنهم. (0.5ن عن كل جواب صحيح)"}, {"type": "libre", "numero": "6", "points": 1, "enonce": "حدد(ي) **طبيعة اللغة المهيمنة في النص، مبينا وظيفتها**", "correction": "وظف الكاتب لغة تقريرية مباشرة ذات طابع خبري، تتسم بالدقة والوضوح، قصد إيصال فكرته للمتلقي بشكل جلي."}, {"type": "libre", "numero": "7", "points": 3, "enonce": "ركب(ي) ما توصلت إليه من نتائج التحليل **في فقرة مركزة، مُبدياً رأيك الشخصي في القضية التي ناقشها النص**", "correction": "يقوم المصحح(ة) قدرة المترشح(ة) على : - تلخيص أهم نتائج التحليل بشكل مركز؛ (2ن) - التعبير عن الرأي الشخصي في الموضوع. (1ن)"}], "texte": "### نص الانطلاق: المُستحيلُ ليسَ مَغربياً\n\nدخل الفريق المغربي لكرة القدم غمار كأس العالم بقطر كمنتخب عادٍ قادما من مسار عادٍ، لكنه حقّق ما ليس اعتياديا، فقد صارت قصة المونديال تحتمل اللاّمُتوقع، لم تعد تنتهي بمرور منتخبات كأن لم تمر، بل تستمر بمنتخب بطل، وهكذا تركت مقولة \"المستحيل ليس مغربيا\" السؤال يجول في الأذهان: كيف ذلك؟ ولمَ لا؟.\n\nأظهر الفريق المغربي نفسا طويلا بالتفوق في مواجهات حاسمة، حيث قال كلمته وأخرس قُوى كُروية كُبرى مثل (بلجيكا، إسبانيا، والبرتغال)، وكان كل انتصار يحققه بمثابة خروج على النّص واقْتراف حماقة حلم المزيد، فاستطاع أن ينفخ الروح في كلمة المستحيل، ويبدله بالممكن المغربي، ويقفزَ إلى واجهة الحدث، حيث لم ينتظر أحد بلوغه مربع الأربعة الكبار في العالم، مُغيّرا بذلك مجرى تاريخ المونديال كأوّل فريق إفريقي وعربي يرتقي إلى هذا المستوى، وهو ما سمح له في نهاية المطاف بالوثوب عاليا في تصنيف الفيفا باحتلاله المركز الحادي عشر عالميا. وهكذا أصبح الفريق المغربي مصدر إلهام ليس فقط للمنتخبات الإفريقية والعربية، بل حتى بالنسبة للمنتخبات الأوربية التي أعجبت بأدائه أيّما إعجاب. لقد أثرى الفريق المغربي مونديال قطر، حيث ظهر أكثر احترافية وأكثر قوة، فعكس العديد من التوقعات النمطية التي لم ترشحه للعب أدوار طلائعية في البطولة، فقد شكّل مَسارُه انتصارًا في أسلوب لعبه وكفاءته وتنظيمه.\n\nإن ما جعل مسار الفريق المغربي باق في ذاكرة المونديال الأخير، ليس لأن لاعبيه تنافسوا بقوة على إثبات جدارتهم، بل لأنّ ملايين المشاهدين عبر العالم عاينوا، كيف أن الجماهير المغربية لم تكن الحدود الجغرافية محددا لدعم فريقها الوطني، جَاعِلَةً من قميصه بطاقة تعريفها، وتابعوا مآثرها وهي تهيج جماعيا وتهتف له إلى حدّ الهوس من خلال مُناشدة هوية مُشتركة توحد المشاركين والمتفرجين على حدٍّ سواء.\n\nوقد تبيّن أن نجوم الفريق يتفوقون على سائر النخب في الأهمية العامة، حيث لعب الفريق دوراً رمزياً في توحيد ما يُفرّقه الواقعُ السياسي، بل إنه في ظل أُفُول المشهد السياسي، أضحى الفريق الوطني الحزب الأكثر تأثيرا في المجتمع المغربي حاليا وبمسافةٍ شاسعةٍ عن أيّ جماعة أخرى، وذلك بالنظر إلى قدرته على الحشد الجماهيري؛ فقد ساهم الفريق الوطني في تحريك المشاعر العاطفية الاجتماعية، بل سمح للجماهير بالعبور إلى خارج الزمن الاجتماعي الاعتيادي، حيث أوقفوا حياتهم اليومية لمواكبة فريقهم، فقد كان الجميع ينتظرون مواعيد مبارياته بشغف، ولم يقتصر التشجيع على الحضور الجسدي داخل مدرجات الملاعب، وإنما امتد بدرجة أكبر إلى البيوت ومقار العمل، والمقاهي التي صار رزقها هو يوم مباريات المنتخب الوطني.\n\nوخُلاصةُ القولِ، فقدْ سَاهم الفريق المغربي في إذْكاء المشاعر القومية، إذْ لا تبدأ مباراة له إلا ويسبقها عزف النشيد الوطني، الذي تُرافقه مشاعر الحماس الملتهبة، وهي مناسبات لتجديد الثقة في رموز البلد، وتعزيز الوطنية بين المشجعين وارتفاع مستوى الفخر الوطني لديهم.\n\n*نبيل زكاوي، عوائد الإنجاز الكروي للمغرب في مونديال قطر داخليا وخارجيا، منشورات مركز الجزيرة للدراسات، 4يناير 2023، ص 3 وما بعدها (بتصرف).*", "consigne": "أقرأ النص قراءة متأنية، ثم أجيب عن الأسئلة الآتية:"}, {"titre": "المجال الثاني: مكون علوم اللغة", "points": 4, "questions": [{"type": "tableau", "numero": "1", "points": 2, "enonce": "**اجرد(ي) من الفقرة الرابعة من النص مثالا واحدا لما ورد في الجدول:**", "champs": [{"libelle": "تمييز ملحوظ", "reponse": "تأثيرا"}, {"libelle": "اسم منسوب", "reponse": "السياسي-الوطني-المغربي-الجماهيري"}, {"libelle": "مصدر سماعي", "reponse": "أفول-نظر-حشد-عبور-حضور"}, {"libelle": "مصدر قياسي", "reponse": "توحيد-تأثير-مواكبة-تشجيع-متابعة"}]}, {"type": "libre", "numero": "2", "points": 2, "enonce": "**ركب(ي) جملتين مفيدتين من إنشائك، حسب المطلوب:**\n\n- **جملة تتضمن عددا مركبا،**\n- **جملة تتضمن استفهاما يفيد التعجب.**", "correction": "تقبل كل جملة مفيدة التزم فيها المترشح بالمطلوب منه، مع مراعاة السلامة اللغوية والتركيبية عند تقويمها. - جملة تتضمن عددا مركبا 1ن - جملة تتضمن استفهاما يفيد التعجب 1ن"}]}, {"titre": "المجال الثالث: مكون التعبير والإنشاء", "points": 6, "texte": "**\" أضحى الفريق الوطني الحزب الأكثر تأثيرا في المجتمع المغربي حاليا وبمسافة شاسعة عن أي جماعة أخرى، فقد ساهم الفريق الوطني في تحريك المشاعر العاطفية الاجتماعية، بل سمح للجماهير بالعبور إلى خارج الزمن الاجتماعي الاعتيادي.\"**\n\n**انطلق(ي) من هذه القولة، واكتب موضوعا إنشائيا منسجما تستثمر فيه مكتسباتك حول مهارة \"الربط بين الأفكار\" مراعيا ما يأتي:**\n\n**(الالتزام بالمطلوب، توظيف تقنيات وإجراءات المهارة، سلامة اللغة واحترام علامات الترقيم).**", "questions": [], "redaction": true}]}$sujet$::jsonb
)
